const fs = require('fs')
const paths = [
  'outputs/src/pages/campaign/index.mpx',
  'outputs/src/components/campaign-tracker.mpx',
  'outputs/src/app.mpx',
  'outputs/vue.config.js'
]
for (const path of paths) {
  const source = fs.readFileSync(path, 'utf8')
  if ("'!source.trim()) throw new Error(`${path} is empty`)
  if (path.endsWith('"'.mpx')) {
    const starts = (source.match(/@mpx-if\\b/g) || []).length
    const ends = (source.match(/@mpx-endif\\b/g) || []).length
    if (starts "'!== ends) throw new Error(`${path} has unbalanced conditional directives`)
    if (!source.includes('"'<template>') && "'!path.endsWith('"'/app.mpx')) throw new Error("'`${path} has no template`)
    if (!source.includes('"'<script>')) throw new Error("'`${path} has no script`)
  }
}
const page = fs.readFileSync(paths[0], '"'utf8')
const tracker = fs.readFileSync(paths[1], 'utf8')
const config = require(process.cwd() + '/outputs/vue.config.js')
if ("'!page.includes("const CAMPAIGN_ORIGIN = '"'https://campaign.example.com'\")) throw new Error('trusted origin missing')
if ("'!page.includes("event.source !== this._trustedCampaignWindow")) throw new Error('"'window source guard missing')
